/**
 * Assessment from photos and videos the user already has. Several files at once: every photo and every movement
 * passage of a video is recognised (FPA-EXPR) and shown for confirmation, the calmest image is the rest reference,
 * missing movements are named with what they would add (FPA-COV), and the analysis is the unchanged FPA-GEOM with
 * landmark tracking. Files are processed in memory only and never stored or sent.
 */
import { useMemo, useState } from 'preact/hooks';
import {
  MOVEMENT_TASKS,
  analyzeSession,
  assessFrame,
  classifyExpression,
  expressionFeatures,
  isScoredTask,
  pickRestIndex,
  restContext,
  scoreCoverage,
  segmentFrames,
  type ExpressionLabel,
  type FrameGuess,
  type FrameObservation,
  type MovementTaskId,
  type QualityIssue,
  type RestContext,
  type TaskId,
} from '../../core';
import { captureDate } from '../../data/exif';
import { createSessionRecord } from '../../data/records';
import { actions, useApp } from '../../data/store';
import { CaptureTracker, type Grabbed } from '../../vision/captureTracker';
import { grabVideoFrame, openVideo, seekVideo } from '../../vision/videoFile';
import { AppBar, Notice } from '../components/common';
import { Icon } from '../icons';
import { ISSUE_LABEL, TASK_LABEL } from '../labels';
import { navigate } from '../router';
import { showScales } from '../role';

/** Video frames analysed per second, and the longest stretch of a video that is read. */
const FPS = 5;
const MAX_VIDEO_S = 180;
/** Below this winner-minus-runner-up margin the automatic label is marked "확인 필요". */
const SURE = 0.3;

type Choice = TaskId | 'skip';

interface Frame {
  t: number;
  obs: FrameObservation;
}

interface Item {
  key: string;
  kind: 'photo' | 'video';
  name: string;
  thumb: string;
  /** Photo: the image as the detector saw it (kept for tracking). */
  canvas?: HTMLCanvasElement;
  /** Photo: its detection; video: the frames of the passage used for the analysis. */
  frames: Frame[];
  /** Video passage. */
  file?: File;
  start?: number;
  end?: number;
  auto: ExpressionLabel;
  sure: boolean;
  choice: Choice;
  note: string | null;
}

interface Scanned {
  file: File;
  frames: Frame[];
}

const CHOICES: { value: Choice; label: string }[] = [
  { value: 'rest', label: '편안히 있기 (안정)' },
  ...MOVEMENT_TASKS.map((t) => ({ value: t as Choice, label: TASK_LABEL[t] })),
  { value: 'skip', label: '사용 안 함' },
];

const hasFace = (o: FrameObservation) => o.landmarks.length >= 468 * 3;
const mmss = (t: number) => `${Math.floor(t / 60)}:${String(Math.floor(t % 60)).padStart(2, '0')}`;
const dayInput = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

function loadImage(file: File): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      URL.revokeObjectURL(url);
      resolve(img);
    };
    img.onerror = () => reject(new Error('image'));
    img.src = url;
  });
}

/** The photo as a canvas (long edge ≤ 1600 px: the eval harness found no accuracy change down to 720 px), flipped back if mirrored. */
function photoCanvas(img: HTMLImageElement, mirrored: boolean): HTMLCanvasElement {
  const s = Math.min(1, 1600 / Math.max(img.naturalWidth, img.naturalHeight));
  const c = document.createElement('canvas');
  c.width = Math.round(img.naturalWidth * s);
  c.height = Math.round(img.naturalHeight * s);
  const ctx = c.getContext('2d')!;
  if (mirrored) {
    ctx.translate(c.width, 0);
    ctx.scale(-1, 1);
  }
  ctx.drawImage(img, 0, 0, c.width, c.height);
  return c;
}

function thumbOf(c: HTMLCanvasElement): string {
  const s = 240 / Math.max(c.width, c.height);
  const t = document.createElement('canvas');
  t.width = Math.round(c.width * s);
  t.height = Math.round(c.height * s);
  t.getContext('2d')!.drawImage(c, 0, 0, t.width, t.height);
  return t.toDataURL('image/jpeg', 0.8);
}

export function Upload() {
  const { profile } = useApp();
  const scales = showScales(profile);
  const [mirrored, setMirrored] = useState(false);
  const [phase, setPhase] = useState<'pick' | 'busy' | 'review'>('pick');
  const [msg, setMsg] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [items, setItems] = useState<Item[]>([]);
  const [restKey, setRestKey] = useState<string | null>(null);
  const [date, setDate] = useState<{ value: string; source: 'exif' | 'file' | 'user' } | null>(null);
  const rest = items.find((i) => i.key === restKey) ?? null;
  const chosen = (t: MovementTaskId) => items.filter((i) => i.choice === t && i.key !== restKey);
  // Detection-only preview of what the chosen images cover (the saved analysis tracks the landmarks).
  const preview = useMemo(() => {
    if (!rest || !profile) return null;
    return analyzeSession({
      affectedSide: profile.affectedSide,
      mode: 'photo',
      rest: rest.frames.map((f) => f.obs),
      tasks: Object.fromEntries(MOVEMENT_TASKS.map((t) => [t, chosen(t).flatMap((i) => i.frames.map((f) => f.obs))])),
    });
  }, [items, restKey, profile?.affectedSide]);
  if (!profile) return null;
  const coverage = preview ? scoreCoverage(preview) : null;
  const missing = MOVEMENT_TASKS.filter((t) => isScoredTask(t) && chosen(t).length === 0);

  const read = async (list: FileList | null) => {
    const files = [...(list ?? [])];
    if (!files.length) return;
    setError(null);
    setPhase('busy');
    try {
      const { getEngine } = await import('../../vision/landmarker');
      const engine = await getEngine(setMsg);
      const photos: Item[] = [];
      const videos: Scanned[] = [];
      for (const [n, file] of files.entries()) {
        if (file.type.startsWith('video/')) {
          const v = await openVideo(file);
          const frames: Frame[] = [];
          const end = Math.min(v.duration, MAX_VIDEO_S);
          for (let t = 0; t < end; t += 1 / FPS) {
            setMsg(`영상 ${n + 1}/${files.length} 분석 중 · ${mmss(t)} / ${mmss(end)}`);
            await seekVideo(v.video, t);
            frames.push({ t, obs: await engine.detectImage(grabVideoFrame(v.video), mirrored) });
          }
          v.close();
          videos.push({ file, frames });
        } else if (file.type.startsWith('image/')) {
          setMsg(`사진 ${n + 1}/${files.length} 분석 중`);
          const canvas = photoCanvas(await loadImage(file), mirrored);
          const obs = await engine.detectImage(canvas);
          const q = assessFrame(obs);
          photos.push({
            key: `p${n}-${file.name}`,
            kind: 'photo',
            name: file.name,
            thumb: thumbOf(canvas),
            canvas,
            frames: [{ t: 0, obs }],
            auto: 'other',
            sure: false,
            choice: 'skip',
            note: hasFace(obs) ? (q.ok ? null : q.issues.map((i) => ISSUE_LABEL[i]).join(', ')) : '얼굴을 찾지 못함',
          });
        }
      }
      if (!date && files[0]) {
        const d = await captureDate(files[0]);
        setDate({ value: dayInput(d.date), source: d.source });
      }
      setMsg('동작 알아보는 중…');
      const next = await recognise([...items.filter((i) => i.kind === 'photo'), ...photos], [...scannedOf(items), ...videos], restKey);
      setItems(next.items);
      setRestKey(next.restKey);
      setPhase('review');
      setMsg('');
    } catch (e) {
      console.warn(e);
      setError('파일을 분석하지 못했습니다. 다른 사진이나 영상으로 다시 시도해 주세요.');
      setPhase(items.length ? 'review' : 'pick');
    }
  };

  const setChoice = (key: string, choice: Choice) => {
    const item = items.find((i) => i.key === key);
    if (choice === 'rest' && item?.kind === 'photo') {
      // One rest reference: the new one takes over. Photos are recognised again against it.
      void recognise(
        items.filter((i) => i.kind === 'photo'),
        scannedOf(items),
        key,
      ).then((n) => {
        setItems(n.items);
        setRestKey(n.restKey);
      });
      return;
    }
    if (choice === 'rest') {
      setItems((xs) => xs.map((i) => (i.key === restKey ? { ...i, choice: 'skip' } : i)));
      setRestKey(key);
      return;
    }
    if (key === restKey) setRestKey(null);
    setItems((xs) => xs.map((i) => (i.key === key ? { ...i, choice } : i)));
  };

  const analyze = async () => {
    if (!rest) return;
    setPhase('busy');
    setMsg('얼굴 점 추적 중…');
    try {
      const { getEngine } = await import('../../vision/landmarker');
      const engine = await getEngine();
      const tk = new CaptureTracker();
      const videoCache = new Map<File, Awaited<ReturnType<typeof openVideo>>>();
      const canvasAt = async (item: Item, f: Frame): Promise<HTMLCanvasElement> => {
        if (item.canvas) return item.canvas;
        let v = videoCache.get(item.file!);
        if (!v) {
          v = await openVideo(item.file!);
          videoCache.set(item.file!, v);
        }
        await seekVideo(v.video, f.t);
        const c = grabVideoFrame(v.video);
        if (mirrored) {
          const m = document.createElement('canvas');
          [m.width, m.height] = [c.width, c.height];
          const ctx = m.getContext('2d')!;
          ctx.translate(c.width, 0);
          ctx.scale(-1, 1);
          ctx.drawImage(c, 0, 0);
          return m;
        }
        return c;
      };
      const restFrame = rest.frames[0]!;
      tk.setRef(await canvasAt(rest, restFrame), restFrame.obs);
      const grab = async (list: Item[]) => {
        const g: Grabbed[] = [];
        for (const item of list)
          for (const f of item.frames) {
            const gray = tk.grab(await canvasAt(item, f), f.obs);
            if (gray) g.push({ obs: f.obs, gray });
          }
        return g;
      };
      const restGrabbed = await grab([{ ...rest, frames: rest.frames.slice(1) }]);
      const input: Partial<Record<TaskId, FrameObservation[]>> = {
        rest: tk.trackTask(
          'rest',
          rest.frames.map((f) => f.obs),
          restGrabbed,
        ),
      };
      for (const t of MOVEMENT_TASKS) {
        const list = chosen(t);
        if (!list.length) continue;
        input[t] = tk.trackTask(
          t,
          list.flatMap((i) => i.frames.map((f) => f.obs)),
          await grab(list),
        );
      }
      videoCache.forEach((v) => v.close());
      try {
        await tk.addMirror('eyeClose', (c) => engine.detectImage(c));
      } catch (e) {
        console.warn('eye mirror step skipped', e);
      }
      const r = analyzeSession({
        affectedSide: profile.affectedSide,
        mode: 'photo',
        rest: input.rest ?? [],
        tasks: Object.fromEntries(MOVEMENT_TASKS.map((t) => [t, input[t] ?? []])),
      });
      if (r.status === 'failed') {
        const why = topIssues(r.restQuality?.issueCounts);
        setError(
          `기준(안정) ${rest.kind === 'video' ? '장면' : '사진'}이 촬영 기준에 맞지 않아 분석할 수 없습니다${why ? `: ${why}` : ''}. 다른 사진·장면을 안정으로 골라 주세요.`,
        );
        setPhase('review');
        return;
      }
      const at = date ? new Date(`${date.value}T12:00:00`) : new Date();
      const rec = await createSessionRecord({ analysis: r, profile, mode: 'photo', engine: engine.info, camera: null, at });
      await actions.addSession(rec);
      navigate(`/session/${rec.id}`);
    } catch (e) {
      console.warn(e);
      setError('분석 중 문제가 생겼습니다. 다시 시도해 주세요.');
      setPhase('review');
    }
  };

  const picker = (label: string, primary: boolean) => (
    <label class={`btn block ${primary ? 'primary' : ''}`}>
      <Icon name="upload" /> {label}
      <input type="file" accept="image/*,video/*" multiple hidden onChange={(e) => read((e.target as HTMLInputElement).files)} />
    </label>
  );

  return (
    <>
      <AppBar title="사진·영상으로 평가" sub="이미 찍어 둔 사진·영상 · 이 기기 안에서만 분석" onBack />
      <main class="main">
        {phase === 'pick' && (
          <>
            <div class="card">
              <p class="small" style={{ margin: 0 }}>
                여러 장을 한 번에 골라도 됩니다. 앱이 사진마다, 영상은 구간마다 어떤 동작인지 알아본 뒤 확인을 받습니다.
              </p>
              <ul class="small ink2" style={{ margin: '6px 0 0', paddingLeft: '18px' }}>
                <li>
                  <b>편안히 있는(안정) 사진이 꼭 한 장</b> 있어야 합니다. 안정 사진과 비교해야 동작을 정확히 알아봅니다.
                </li>
                <li>같은 날, 같은 자리에서 찍은 것끼리 올려 주세요.</li>
                <li>영상은 동작마다 2–3초 유지하면 가장 정확합니다. 말하는 부분은 자동으로 뺍니다.</li>
                <li>사진·영상은 저장하거나 보내지 않고, 얼굴 점 좌표와 측정값만 기록합니다.</li>
              </ul>
            </div>
            <label class="check">
              <input type="checkbox" checked={mirrored} onChange={(e) => setMirrored((e.target as HTMLInputElement).checked)} />
              <span class="small">
                <b>거울처럼 좌우 반전되어 저장된 셀카입니다.</b> 잘못 고르면 마비 쪽이 뒤바뀌어 분석됩니다. (파일을 고르기 전에 선택)
              </span>
            </label>
            {picker('사진·영상 고르기', true)}
          </>
        )}

        {phase === 'busy' && (
          <div class="card center">
            <p class="small">{msg || '준비 중…'}</p>
          </div>
        )}

        {error && (
          <Notice tone="danger">
            <span class="small">{error}</span>
          </Notice>
        )}

        {phase === 'review' && (
          <>
            {!rest && (
              <Notice tone="warn">
                <span class="small">
                  안정 사진을 찾지 못했습니다. 편안히 있는 사진을 추가하거나, 아래에서 한 장을 ‘편안히 있기’로 골라 주세요.
                </span>
              </Notice>
            )}
            <div class="card tight">
              <label class="field">
                <span class="small">촬영 날짜</span>
                <input
                  type="date"
                  value={date?.value ?? ''}
                  onChange={(e) => setDate({ value: (e.target as HTMLInputElement).value, source: 'user' })}
                />
              </label>
              <span class="xsmall muted">
                {date?.source === 'exif'
                  ? '사진 정보에서 읽었습니다.'
                  : date?.source === 'file'
                    ? '파일 날짜입니다. 실제 촬영일과 다르면 고쳐 주세요.'
                    : ''}{' '}
                예전 사진이면 그 날짜로 기록되어 경과 그래프에 들어갑니다.
              </span>
              {date && profile.onsetDate && date.value < profile.onsetDate.slice(0, 10) && (
                <Notice tone="warn">
                  <span class="small">발병일보다 앞선 날짜입니다. 마비 전 사진이면 비교 기준으로만 참고하세요.</span>
                </Notice>
              )}
            </div>

            <div class="tiles">
              {items.map((i) => (
                <div class="tile" style={{ gap: '6px', outline: i.key === restKey ? '2px solid var(--accent)' : undefined }}>
                  <div style={{ aspectRatio: '3/4', borderRadius: '8px', background: 'var(--grid)', overflow: 'hidden' }}>
                    <img src={i.thumb} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                  </div>
                  <span class="xsmall muted" style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                    {i.kind === 'video' ? `영상 ${mmss(i.start ?? 0)}–${mmss(i.end ?? 0)}` : i.name}
                  </span>
                  <select
                    aria-label="동작"
                    value={i.key === restKey ? 'rest' : i.choice}
                    onChange={(e) => setChoice(i.key, (e.target as HTMLSelectElement).value as Choice)}
                  >
                    {CHOICES.map((c) => (
                      <option value={c.value}>{c.label}</option>
                    ))}
                  </select>
                  <span class="xsmall" style={{ color: i.note || !i.sure ? 'var(--warn-ink, #8a4a06)' : 'var(--ink2)' }}>
                    {i.key === restKey ? `기준(안정)${i.note ? ` · ${i.note}` : ''}` : (i.note ?? (i.sure ? '자동 인식' : '확인 필요'))}
                  </span>
                </div>
              ))}
            </div>

            <div class="card tight">
              <b class="small">담긴 동작</b>
              <div class="row" style={{ flexWrap: 'wrap', gap: '6px' }}>
                {MOVEMENT_TASKS.map((t) => (
                  <span class={`chip ${chosen(t).length ? 'accent' : ''}`}>
                    {chosen(t).length ? '✓' : '—'} {TASK_LABEL[t]}
                  </span>
                ))}
              </div>
              {missing.length > 0 && (
                <p class="small" style={{ margin: 0 }}>
                  빠진 동작이 있으면 종합 점수 대신 {scales ? '가능한 범위를' : '부위별 비율만'} 보여 줍니다. 더 올리면 가장 도움이 되는
                  동작: <b>{TASK_LABEL[(coverage?.gain[0]?.task ?? missing[0])!]}</b>
                </p>
              )}
            </div>

            <button class="btn primary block" disabled={!rest || MOVEMENT_TASKS.every((t) => chosen(t).length === 0)} onClick={analyze}>
              분석하고 저장
            </button>
            {picker('사진·영상 더 추가', false)}
          </>
        )}
      </main>
    </>
  );
}

/** The most frequent quality-gate reasons, as the camera screen words them. */
function topIssues(counts: Partial<Record<QualityIssue, number>> | undefined): string {
  return Object.entries(counts ?? {})
    .sort((a, b) => b[1]! - a[1]!)
    .slice(0, 2)
    .map(([k]) => ISSUE_LABEL[k as QualityIssue])
    .join(', ');
}

/** A note when most frames of a passage fail the assessment's quality gate (they will be left out). */
function gateNote(obs: FrameObservation[]): string | null {
  const counts: Partial<Record<QualityIssue, number>> = {};
  let bad = 0;
  for (const o of obs) {
    const q = assessFrame(o);
    if (q.ok) continue;
    bad++;
    for (const i of q.issues) counts[i] = (counts[i] ?? 0) + 1;
  }
  return bad * 2 > obs.length ? `기준 미달: ${topIssues(counts)}` : null;
}

/** The scanned videos behind the video items (to re-segment against a new rest reference). */
function scannedOf(items: Item[]): Scanned[] {
  const seen = new Map<File, Frame[]>();
  for (const i of items) if (i.kind === 'video' && i.file && !seen.has(i.file)) seen.set(i.file, (i as Item & { all?: Frame[] }).all ?? []);
  return [...seen].map(([file, frames]) => ({ file, frames }));
}

/**
 * Picks the rest reference (the given key, else the calmest photo, else the calmest video frame), labels every photo
 * against it and cuts every video into passages against its own calmest frame.
 */
async function recognise(photos: Item[], videos: Scanned[], wantKey: string | null): Promise<{ items: Item[]; restKey: string | null }> {
  const alone = (o: FrameObservation) => classifyExpression(expressionFeatures(o, null));
  let restItem = photos.find((p) => p.key === wantKey && hasFace(p.frames[0]!.obs)) ?? null;
  if (!restItem) {
    const i = pickRestIndex(photos.map((p) => p.frames[0]!.obs));
    restItem = i >= 0 ? photos[i]! : null;
  }
  const out: Item[] = [];
  let restKey = restItem?.key ?? null;
  const ctx: RestContext | null = restItem ? restContext(restItem.frames[0]!.obs) : null;
  for (const p of photos) {
    const o = p.frames[0]!.obs;
    if (!hasFace(o)) {
      out.push({ ...p, auto: 'other', sure: false, choice: 'skip' });
      continue;
    }
    if (p === restItem) {
      out.push({ ...p, auto: 'rest', sure: true, choice: 'rest' });
      continue;
    }
    const g = classifyExpression(expressionFeatures(o, ctx));
    const choice: Choice = g.label === 'other' || g.label === 'rest' ? 'skip' : g.label;
    out.push({ ...p, auto: g.label, sure: !!ctx && g.confidence >= SURE, choice });
  }
  for (const [vi, v] of videos.entries()) {
    const face = v.frames.map((f) => hasFace(f.obs));
    let calm = -1;
    let calmP = -1;
    v.frames.forEach((f, i) => {
      if (!face[i]) return;
      const g = alone(f.obs);
      const s = g.probs.rest + 0.5 * g.strength.rest;
      if (s > calmP) [calmP, calm] = [s, i];
    });
    const vctx = calm >= 0 ? restContext(v.frames[calm]!.obs) : null;
    const guesses: FrameGuess[] = v.frames.map((f, i) => {
      const g = classifyExpression(expressionFeatures(f.obs, vctx));
      const label = face[i] ? g.label : null;
      return { t: f.t, label, prob: label && label !== 'other' ? g.probs[label] : 1, strength: g.strength };
    });
    const segs = segmentFrames(guesses);
    // The video's rest passage: the one around its calmest frame, else the rest passage with the most calm frames.
    const calmT = calm >= 0 ? v.frames[calm]!.t : -1;
    const rests = segs.filter((s) => s.label === 'rest' && s.held.length);
    const restSeg = restKey
      ? null
      : (rests.find((s) => s.start <= calmT && calmT <= s.end) ?? rests.sort((a, b) => b.held.length - a.held.length)[0] ?? null);
    const opened = await openVideo(v.file);
    for (const [si, s] of segs.entries()) {
      if (s.label === null || s.label === 'other' || !s.held.length) continue;
      if (s.label === 'rest' && s !== restSeg) continue;
      await seekVideo(opened.video, s.peakT);
      const key = `v${vi}-${si}-${v.file.name}`;
      const item: Item & { all: Frame[] } = {
        key,
        kind: 'video',
        name: v.file.name,
        thumb: thumbOf(grabVideoFrame(opened.video)),
        file: v.file,
        frames:
          s.label === 'rest' && calmT >= s.start && calmT <= s.end
            ? [v.frames[calm]!, ...s.held.filter((i) => i !== calm).map((i) => v.frames[i]!)]
            : s.held.map((i) => v.frames[i]!),
        start: s.start,
        end: s.end,
        auto: s.label,
        sure: true,
        choice: s.label,
        note: gateNote(s.held.map((i) => v.frames[i]!.obs)),
        all: v.frames,
      };
      if (s.label === 'rest') restKey = key;
      out.push(item);
    }
    opened.close();
  }
  return { items: out, restKey };
}
